// 1935 forest mask baked from the Latvian Army 1:75k sheet by data/bake-forest1935.mjs.
// 220x220 cells (40m) over the sim square; byte = forest fraction 0..255 from
// green-fill voting with linework excluded and a 3x3 median cleanup.
export const F35_N = 220;
const F35_B64 = "";
let _m = null;
export function forest1935At(x, z) {
  if (!_m) {
    const bin = atob(F35_B64);
    _m = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) _m[i] = bin.charCodeAt(i);
  }
  const u = ((x - 500) / 8800) + 0.5, v = ((z - 1700) / 8800) + 0.5;
  if (u < 0 || v < 0 || u >= 1 || v >= 1) return 0;
  return _m[Math.floor(v * 220) * 220 + Math.floor(u * 220)] / 255;
}
